CREATE TABLE trade_order(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(64) NOT NULL UNIQUE,member_id BIGINT NOT NULL,idempotency_key VARCHAR(100) NOT NULL,request_hash CHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,goods_fen BIGINT NOT NULL DEFAULT 0,discount_fen BIGINT NOT NULL DEFAULT 0,freight_fen BIGINT NOT NULL DEFAULT 0,payable_fen BIGINT NOT NULL DEFAULT 0,coupon_id BIGINT NULL,zero_settled BOOLEAN NOT NULL DEFAULT FALSE,close_requested BOOLEAN NOT NULL DEFAULT FALSE,active_after_sale_no VARCHAR(64) NULL,created_at DATETIME(6) NOT NULL,expires_at DATETIME(6) NOT NULL,paid_at DATETIME(6) NULL,completed_at DATETIME(6) NULL,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE(member_id,idempotency_key),INDEX idx_order_expiry(status,expires_at,id),INDEX idx_order_member(member_id,created_at,id),CHECK(goods_fen>=0 AND discount_fen>=0 AND freight_fen>=0 AND payable_fen>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_item(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(64) NOT NULL,sku_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,specs VARCHAR(2048) NOT NULL,image_url VARCHAR(2048) NULL,quantity INT NOT NULL,unit_price_fen BIGINT NOT NULL,payable_fen BIGINT NOT NULL,UNIQUE(order_no,sku_id),FOREIGN KEY(order_no) REFERENCES trade_order(order_no),CHECK(quantity>0 AND unit_price_fen>=0 AND payable_fen>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_address(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(64) NOT NULL UNIQUE,snapshot_json JSON NOT NULL,FOREIGN KEY(order_no) REFERENCES trade_order(order_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_status_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(64) NOT NULL,from_status VARCHAR(32) NULL,to_status VARCHAR(32) NOT NULL,reason VARCHAR(255) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_no) REFERENCES trade_order(order_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
